import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, DirectionalLight, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Store resources for cleanup
  const _primitives = [];
  const _timelines = [];
  let _gltf = null;

  // Load GLB mesh (synchronously return root, async load will populate later)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      _gltf = gltf;
      root.add(gltf.scene);
    });
  }

  // Accent rim light (using spec accent color)
  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || config.colors || {};
  const accentHex = colors.accent || '#ff2a38';
  const rimLight = new DirectionalLight(new Color(accentHex), 0.8);
  // Position light to act as a rim (behind the subject, slightly offset)
  rimLight.position.set(0, 0, -5);
  root.add(rimLight);

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const name = prim.name;
      const params = prim.params || {};
      const trigger = prim.trigger; // not used directly; primitives handle it internally
      if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
        const instance = ctx.primitives[name](root, params);
        _primitives.push(instance);
      }
    }
  }

  // Event handlers container
  root.userData.handlers = {};

  // Hover effect: rise-in (subtle, 0.15 scene units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: `+=${0.15}`,
    duration: 0.7,
    ease: 'power3.out',
  });
  _timelines.push(hoverTimeline);

  root.userData.handlers.hover = () => {
    hoverTimeline.restart();
  };
  // Optional: reset on hover out
  root.userData.handlers.hoverout = () => {
    hoverTimeline.reverse();
  };

  // Click effect: emit navigation/event
  root.userData.handlers.click = () => {
    ctx.emit('hub-collection.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    for (const tl of _timelines) {
      tl.kill();
    }
    // Cleanup primitives
    for (const p of _primitives) {
      if (p && typeof p.cleanup === 'function') {
        p.cleanup();
      }
    }
    // Dispose GLTF resources
    if (_gltf && _gltf.scene) {
      _gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
    // Dispose rim light
    rimLight.dispose && rimLight.dispose();
  };

  return root;
}
